class Solution {
public:
    int maximumCost(int n, vector<vector<int>>& highways, int k) {
        if (k >= n) return -1;
        vector<vector<pair<int, int>>> graph(n);
        for (auto& e : highways) {
            graph[e[0]].push_back({e[1], e[2]});
            graph[e[1]].push_back({e[0], e[2]});
        }
        int states = 1 << n;
        vector<vector<int>> dp(states, vector<int>(n, -1));
        for (int i = 0; i < n; ++i) dp[1 << i][i] = 0;
        int answer = -1;
        for (int mask = 1; mask < states; ++mask) {
            int count = __builtin_popcount((unsigned)mask);
            if (count > k + 1) continue;
            for (int u = 0; u < n; ++u) if (dp[mask][u] >= 0) {
                if (count == k + 1) { answer = max(answer, dp[mask][u]); continue; }
                for (auto edge : graph[u]) if (!(mask & (1 << edge.first))) {
                    int next = mask | (1 << edge.first);
                    dp[next][edge.first] = max(dp[next][edge.first], dp[mask][u] + edge.second);
                }
            }
        }
        return answer;
    }
};
